import heapq

def match(orders):
    trades = []
    info = {}  # id -> {'qty':int, 'price':int, 'side':str, 'active':bool}
    buy_heap = []   # entries: (-price, time, id)
    sell_heap = []  # entries: (price, time, id)

    def clean_top(heap):
        while heap:
            oid = heap[0][2]
            rec = info.get(oid)
            if rec is None or not rec['active'] or rec['qty'] <= 0:
                heapq.heappop(heap)
            else:
                return heap[0]
        return None

    for t, order in enumerate(orders):
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            rec = info.get(oid)
            if rec is not None and rec['active'] and rec['qty'] > 0:
                rec['active'] = False
            continue

        oid = order[1]
        side = order[2]

        if typ == 'market':
            qty = order[3]
            price = None
        else:
            price = order[3]
            qty = order[4]

        opposite = sell_heap if side == 'buy' else buy_heap

        while qty > 0:
            top = clean_top(opposite)
            if top is None:
                break
            resting_price = -top[0] if side == 'buy' else top[0]

            if typ == 'market':
                cond = True
            else:
                if side == 'buy':
                    cond = resting_price <= price
                else:
                    cond = resting_price >= price

            if not cond:
                break

            resting_id = top[2]
            rec = info[resting_id]
            trade_qty = min(qty, rec['qty'])

            if side == 'buy':
                buy_id = oid
                sell_id = resting_id
            else:
                buy_id = resting_id
                sell_id = oid

            trades.append([buy_id, sell_id, resting_price, trade_qty])

            rec['qty'] -= trade_qty
            qty -= trade_qty

            if rec['qty'] == 0:
                rec['active'] = False

        if typ == 'limit' and qty > 0:
            info[oid] = {'qty': qty, 'price': price, 'side': side, 'active': True}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, t, oid))
            else:
                heapq.heappush(sell_heap, (price, t, oid))
        else:
            # ioc/market leftover discarded, or limit fully filled
            if typ == 'limit' and oid not in info:
                info[oid] = {'qty': 0, 'price': price, 'side': side, 'active': False}

    return trades

